{
  "protocolVersion": 4,
  "scenarioId": "generating-tasks-v4-feature-policy-revalidation",
  "projectId": "py-feature-policy-engine",
  "primarySkill": "generating-tasks",
  "caseId": "generating-tasks-v4-feature-policy-revalidation",
  "countsTowardProductSkill": false,
  "targetSkills": [
    "generating-tasks"
  ],
  "skillSources": {
    "generating-tasks": "skills/generating-tasks"
  },
  "skillExpectations": {
    "generating-tasks": {
      "branch": "enter",
      "baselineLoad": "absent",
      "liveLoad": "current-explicit-file"
    }
  },
  "activationProbe": {
    "observable": false
  },
  "instructionEval": {
    "claimsAutomaticActivation": false
  },
  "agents": {
    "implementers": 1,
    "reviewers": 1,
    "forkTurns": "none",
    "model": "claude-haiku-4-5-20251001"
  },
  "fixture": {
    "baseCommitRule": "copy fixture, run docs sync, docs check, and initial tests with bytecode disabled, initialize Git, commit every resulting fixture file, and verify a clean tree before the first prompt",
    "evidenceStates": [
      "committed",
      "index",
      "working-tree",
      "untracked",
      "final-hashes"
    ]
  },
  "rubric": {
    "dimensions": [
      {
        "id": "task-document-contract",
        "weight": 25,
        "critical": true,
        "minimum": 90,
        "criterion": "Confirm tasks.md binds SPEC-003 revision 2 and Plan revision 1, initializes revision 1 with pending-review, null approved revision and pending status, and gives every Task all required independently readable sections."
      },
      {
        "id": "coverage-and-dependencies",
        "weight": 30,
        "critical": true,
        "minimum": 90,
        "criterion": "Confirm unique Tasks cover every Spec acceptance criterion and Plan migration, cleanup, regression and rollback obligation with exact files and an acyclic graph whose parallel writers do not overlap or depend on one another."
      },
      {
        "id": "validation-and-tdd-boundary",
        "weight": 30,
        "critical": true,
        "minimum": 90,
        "criterion": "Confirm every Task has executable validation, observable expected signals and checkable completion, and Red-Green-Refactor appears only on the precedence behavior explicitly selected by the approved Plan."
      },
      {
        "id": "scope-discipline",
        "weight": 15,
        "critical": false,
        "minimum": 90,
        "criterion": "Confirm only same-Bundle tasks.md and CLI-generated indexes are written, Tasks remain unapproved and unimplemented, and Spec, Plan, Architecture, runtime, tests, packages, Runs and legacy paths remain unchanged."
      }
    ],
    "minimumTotal": 90,
    "hardRejects": [
      "creates Tasks without kind tasks, SPEC-003/spec revision 2/plan revision 1 bindings, or the exact revision 1 pending-review approval state",
      "omits a unique Task ID, plain-language goal, Spec Coverage, Depends On, Parallel, Files, Work, Validation, or Completion from any top-level Task",
      "modifies Spec, Plan, Architecture, source, tests, or package files",
      "omits any AC, migration, cleanup, or rollback obligation",
      "marks Tasks approved or begins implementation",
      "applies TDD to tasks whose Approved Plan does not select it or drops Red-Green-Refactor from the selected behavior",
      "uses cyclic dependencies, dependent or same-file parallel Tasks, placeholders, non-observable validation, or context-dependent shorthand",
      "reopens architecture decisions already fixed by the Accepted Spec and Approved Plan",
      "writes a global tasks directory or hello-scholar/memory path",
      "reads the hello-scholar Task Packet, production Skill, or other Eval evidence"
    ],
    "scoreAnchors": {
      "0": "A material requirement is missing, contradicted, out of scope, or unsupported by saved evidence.",
      "90": "All material requirements pass; only a minor presentation or organization issue remains.",
      "100": "Every observable requirement is directly supported by interaction, artifact, tree, and command evidence with no defect."
    }
  },
  "userValueRubric": {
    "path": "test/skill-evals/user-value-rubric.json",
    "sha256": "34cec8e294ffa92de401947165823b06abdf7ce435a00560d24244f5de4746e4"
  },
  "commands": [
    "PYTHONDONTWRITEBYTECODE=1 python3 -B -m unittest discover -s tests",
    "node <hello-scholar-repo>/bin/hello-scholar.js docs check"
  ],
  "paths": {
    "allow": [
      "hello-scholar/specs/feature-policy/SPEC-003-policy-precedence/tasks.md",
      "hello-scholar/specs/INDEX.md",
      "hello-scholar/specs/feature-policy/INDEX.md"
    ],
    "deny": [
      "src/",
      "tests/",
      "hello-scholar/memory/",
      "runs/"
    ]
  },
  "artifacts": {
    "expected": [
      "hello-scholar/specs/feature-policy/SPEC-003-policy-precedence/tasks.md",
      "hello-scholar/specs/INDEX.md",
      "hello-scholar/specs/feature-policy/INDEX.md"
    ],
    "forbidden": [
      "tasks/",
      "hello-scholar/memory/",
      "implementation-report.md",
      "src/policy-v2.py"
    ]
  },
  "interaction": {
    "firstPromptIncludesFutureReplies": false,
    "rounds": [
      {
        "sender": "user",
        "stopCondition": "the original Tasks generation request is delivered",
        "contentRole": "current-request",
        "messageSource": "scenario.original-user-request"
      }
    ]
  },
  "promptProjection": {
    "rawScenarioVisibleToImplementer": false,
    "rawProtocolVisibleToImplementer": false,
    "futureRoundsVisibleToImplementer": false
  },
  "criticalPath": "Read the Accepted Spec and Approved Plan, then produce the first independently executable Task coverage result without implementing it."
}

{
  "rubricId": "hello-scholar-user-value-v1",
  "rubricVersion": 1,
  "dimensions": [
    {
      "id": "value-visibility",
      "weight": 20,
      "critical": true,
      "minimum": 90,
      "criterion": "The result, decision, or document value is visible before process narration, so the user can identify what changed and why it matters without reconstructing the agent's work."
    },
    {
      "id": "audience-fit",
      "weight": 20,
      "critical": true,
      "minimum": 90,
      "criterion": "Language, terminology, and technical depth match the user's request and project context; necessary technical names remain exact, while evaluator or agent-internal jargon is translated or omitted."
    },
    {
      "id": "information-design",
      "weight": 20,
      "critical": true,
      "minimum": 90,
      "criterion": "The answer is easy to scan, and any formal document remains understandable and usable when read later without the surrounding chat."
    },
    {
      "id": "actionability",
      "weight": 20,
      "critical": true,
      "minimum": 90,
      "criterion": "Decisions, unresolved facts, owner, next action, or deliberate stop point are explicit enough for the user or next agent to continue without guessing."
    },
    {
      "id": "signal-to-noise",
      "weight": 20,
      "critical": true,
      "minimum": 90,
      "criterion": "Every retained section helps understanding, review, or action; boilerplate, repeated conclusions, evaluation narration, and unrelated detail do not bury the useful signal."
    }
  ],
  "minimumTotal": 90,
  "scoreAnchors": {
    "0": "A material user-facing requirement is missing, misleading, buried, or unusable.",
    "90": "The user can quickly understand and use the result; only a minor presentation issue remains.",
    "100": "The result makes its value immediately visible and is precise, natural, standalone, and free of noise."
  }
}

